/* eslint-disable @typescript-eslint/no-explicit-any */
// Golden vectors generated by Accumulate 1.4.6.7's own Go marshaler.
// Binary encoding is consensus-critical: every vector must match byte-for-byte,
// and transaction hashes must match Go's Transaction.GetHash().
import * as fs from "fs";
import * as path from "path";
import { Buffer } from "../src/common/buffer";
import { encode } from "../src/encoding";
import * as core from "../src/core";

type Vector = { name: string; json: any; binaryHex?: string; hashHex?: string };

const vectors: Vector[] = JSON.parse(
  fs.readFileSync(path.join(__dirname, "data", "golden-vectors.json"), "utf8"),
);

const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");

describe("golden vectors (Go marshaler)", () => {
  for (const v of vectors) {
    if (v.name.startsWith("header_")) {
      it(`${v.name} binary`, () => {
        const h = new core.TransactionHeader(v.json);
        expect(hex(encode(h))).toBe(v.binaryHex);
      });
      it(`${v.name} JSON round trip`, () => {
        const h = new core.TransactionHeader(v.json);
        const again = new core.TransactionHeader(JSON.parse(JSON.stringify(h.asObject())));
        expect(hex(encode(again))).toBe(v.binaryHex);
      });
    } else if (v.name.startsWith("hashlockoptions_")) {
      it(`${v.name} binary`, () => {
        const o = new (core as any).HashLockOptions(v.json);
        expect(hex(encode(o))).toBe(v.binaryHex);
      });
    } else if (v.name.startsWith("networkglobals_")) {
      it(`${v.name} binary`, () => {
        const g = new core.NetworkGlobals(v.json);
        expect(hex(encode(g))).toBe(v.binaryHex);
      });
      it(`${v.name} JSON round trip`, () => {
        const g = new core.NetworkGlobals(v.json);
        const again = new core.NetworkGlobals(JSON.parse(JSON.stringify(g.asObject())));
        expect(hex(encode(again))).toBe(v.binaryHex);
      });
    } else if (v.name.startsWith("tx_")) {
      it(`${v.name} binary`, () => {
        const t = new core.Transaction(v.json);
        expect(hex(encode(t))).toBe(v.binaryHex);
      });
      it(`${v.name} hash`, () => {
        const t = new core.Transaction(v.json);
        expect(hex(t.hash())).toBe(v.hashHex);
      });
      it(`${v.name} JSON round trip`, () => {
        const t = new core.Transaction(v.json);
        const again = new core.Transaction(JSON.parse(JSON.stringify(t.asObject())));
        expect(hex(encode(again))).toBe(v.binaryHex);
        expect(hex(again.hash())).toBe(v.hashHex);
      });
    }
  }

  it("transaction type codes", () => {
    expect(core.TransactionType.ReleaseLockedOperation).toBe(0x18);
    expect(core.TransactionType.SyntheticLockedDeposit).toBe(0x37);
  });
});
